import React from "react";
import "./App.css";
import Upload from "./components/Upload";
import About from "./components/About";

function App() {
  return (
    <div className="app-container">

      {/* Navbar */}
      <nav className="navbar">
        <h2>🌊 Garbage Detection</h2>
        <ul>
          <li><a href="#home">Home</a></li>
          <li><a href="#upload">Upload</a></li>
          <li><a href="#about">About</a></li>
        </ul>
      </nav>

      {/* Home Section */}
      <section id="home">
        <h1>Underwater Garbage Detection</h1>
        <p>AI-powered system to detect ocean waste</p>
      </section>

      {/* Upload Section */}
      <section id="upload">
        <Upload />
      </section>

      {/* About Section */}
      <section id="about">
        <h2>About Project</h2>
        <p>
          This project uses YOLOv8 to detect underwater garbage like plastic,
          bottles, and waste materials to help protect marine life.
        </p>
      </section>

      {/* Waves */}
      <div className="wave"></div>
      <div className="wave wave2"></div>
      <div className="wave wave3"></div>

      {/* Bubbles */}
      <div className="bubbles">
        <span></span>
        <span></span>
        <span></span>
        <span></span>
        <span></span>
        <span></span>
        <span></span>
      </div>

    </div>
  );
}

export default App;
